@triton.jit
def _sin_f32(x):
    """``sin(x)`` for an fp32 block: reduce modulo pi, one odd polynomial.

    ``n = round(x/pi)`` (nearest), ``r = x - n*pi`` with a three part
    Cody-Waite split of pi so ``r`` keeps full fp32 accuracy, and
    ``sin(x) = (-1)**n * sin(r)`` with ``|r| <= pi/2``.  The polynomial is the
    odd Taylor/minimax tail up to ``r**13`` (truncation error below 1e-9 on
    that interval, i.e. well inside a fp32 ULP of the result).
    """
    n = tl.math.floor(x * 0.31830988618379067154 + 0.5)
    r = x - n * 3.140625
    r = r - n * 0.00096702593994140625
    r = r - n * 1.5099579909783764e-07
    u = r * r
    p = 1.6059043836821613e-10
    p = p * u - 2.505210838544172e-08
    p = p * u + 2.7557319223985893e-06
    p = p * u - 1.9841269841269841e-04
    p = p * u + 8.3333333333333333e-03
    p = p * u - 1.6666666666666666e-01
    p = p * u + 1.0
    s = r * p
    return tl.where((n.to(tl.int32) & 1) != 0, -s, s)


@triton.jit
def _sin_body(p, n_elements, chunk, BLOCK: tl.constexpr, I64: tl.constexpr):
    """One masked tile of ``x[i] = sin(x[i])`` starting at ``chunk*BLOCK``."""
    if I64:
        offs = chunk.to(tl.int64) * BLOCK + tl.arange(0, BLOCK).to(tl.int64)
    else:
        offs = chunk * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n_elements
    x = tl.load(p + offs, mask=mask, other=0.0)
    y = _sin_f32(x.to(tl.float32))
    tl.store(p + offs, y.to(x.dtype), mask=mask)


@triton.jit
def _sin_flat_kernel(x_ptr, n_elements, BLOCK: tl.constexpr, I64: tl.constexpr):
    """``x[i] = sin(x[i])`` for one flat-addressable (dense) tensor."""
    _sin_body(x_ptr, n_elements, tl.program_id(0), BLOCK, I64)


