@triton.jit
def _sin_strided_kernel(
    x_ptr,
    n_elements,
    s0,
    t0,
    s1,
    t1,
    s2,
    t2,
    s3,
    t3,
    s4,
    t4,
    s5,
    t5,
    s6,
    t6,
    s7,
    t7,
    NDIM: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """Gappy view: map flat logical index -> element offset via div/mod chain.

    ``(s?, t?)`` are the collapsed dims sorted by ascending stride, so the
    fastest varying logical dim has the smallest stride and consecutive lanes
    touch consecutive memory whenever possible.
    """
    pid = tl.program_id(0)
    offs = pid.to(tl.int64) * BLOCK + tl.arange(0, BLOCK).to(tl.int64)
    rem = offs
    off = tl.zeros([BLOCK], dtype=tl.int64)
    if NDIM >= 1:
        off += (rem % s0) * t0
        rem = rem // s0
    if NDIM >= 2:
        off += (rem % s1) * t1
        rem = rem // s1
    if NDIM >= 3:
        off += (rem % s2) * t2
        rem = rem // s2
    if NDIM >= 4:
        off += (rem % s3) * t3
        rem = rem // s3
    if NDIM >= 5:
        off += (rem % s4) * t4
        rem = rem // s4
    if NDIM >= 6:
        off += (rem % s5) * t5
        rem = rem // s5
    if NDIM >= 7:
        off += (rem % s6) * t6
        rem = rem // s6
    if NDIM >= 8:
        off += (rem % s7) * t7
        rem = rem // s7
    mask = offs < n_elements
    x = tl.load(x_ptr + off, mask=mask, other=0.0)
    y = _sin_f32(x.to(tl.float32))
    tl.store(x_ptr + off, y.to(x.dtype), mask=mask)


