def _is_flat(t):
    """True when ``[data_ptr, data_ptr + numel)`` is exactly this tensor."""
    if t.is_contiguous():
        return True
    if t.numel() <= 1:
        return True
    expected = 1
    for st, sz in sorted((s, z) for s, z in zip(t.stride(), t.shape) if z != 1):
        if st != expected:
            return False
        expected *= sz
    return True


def _collapse(t):
    """Dims sorted by ascending stride, adjacent ones merged, size-1 dropped."""
    dims = [(sz, st) for sz, st in zip(t.shape, t.stride()) if sz != 1]
    if not dims:
        return []
    dims = sorted(dims, key=lambda d: d[1])
    out = []
    for sz, st in dims:
        if out and out[-1][1] * out[-1][0] == st:
            psz, pst = out[-1]
            out[-1] = (psz * sz, pst)
        else:
            out.append((sz, st))
    return out


def _block_for(esize):
    # 4096 elements per program: the fp32 polynomial evaluation keeps several
    # full-width temporaries live in the 192KB unified buffer, and 8192 wide
    # (fp16/bf16 input, fp32 math) overflows it at compile time.
    if esize <= 4:
        return 4096
    return 2048


_PAD_S, _PAD_T = [1] * 8, [0] * 8


def _launch_flat_batch(batch):
    """One launch for 1..16 flat tensors of the same dtype."""
    nt = len(batch)
    numels = [t.numel() for t in batch]
    block = _block_for(batch[0].element_size())
    maxn = max(numels)
    chunks = (maxn + block - 1) // block
    if nt == 1:
        _sin_flat_kernel[(chunks,)](batch[0], numels[0], block, maxn > _INT32_MAX)
        return
    ptrs = list(batch)
    counts = numels
    if nt < _MAX_NT:
        pad = _MAX_NT - nt
        ptrs += [batch[0]] * pad
        # zero counts: an untraced padding branch, and even a traced one would
        # be fully masked instead of touching batch[0]
        counts = numels + [0] * pad
    _sin_multi_kernel[(nt, chunks)](*ptrs, *counts, nt, block, maxn > _INT32_MAX)


def _apply_strided(t):
    numel = t.numel()
    block = _block_for(t.element_size())
    grid = ((numel + block - 1) // block,)
    if torch._debug_has_internal_overlap(t) == 1:
        raise RuntimeError(
            "unsupported operation: more than one element of the written-to "
            "tensor refers to a single memory location. Please clone() the "
            "tensor before performing the operation."
        )
    dims = _collapse(t)
    ndim = len(dims)
    if ndim == 0:
        _sin_flat_kernel[grid](t, numel, block, numel > _INT32_MAX)
        return
    if ndim > 8:
        raise NotImplementedError("foreach_sin_: unsupported tensor rank")
    ss = list(_PAD_S)
    ts = list(_PAD_T)
    for i, (sz, st) in enumerate(dims):
        ss[i] = sz
        ts[i] = st
    _sin_strided_kernel[grid](
        t,
        numel,
        ss[0],
        ts[0],
        ss[1],
        ts[1],
        ss[2],
        ts[2],
        ss[3],
        ts[3],
        ss[4],
        ts[4],
        ss[5],
        ts[5],
        ss[6],
        ts[6],
        ss[7],
        ts[7],
        ndim,
        block,
    )


def _has_alias(tensors):
    """True when two list elements share storage bytes.

    ATen applies the operator element by element in list order, so results for
    aliased list elements depend on that order.  Fusing reorders the writes, so
    an aliased list falls back to the sequential per-tensor path instead.
    """
    spans = []
    for t in tensors:
        n = t.numel()
        if n:
            span = 1
            for sz, st in zip(t.shape, t.stride()):
                span += (sz - 1) * st
            p = t.data_ptr()
            spans.append((p, p + span * t.element_size()))
    if len(spans) < 2:
        return False
    spans = sorted(spans)
    prev_end = spans[0][1]
    for start, end in spans[1:]:
        if start < prev_end:
            return True
        if end > prev_end:
            prev_end = end
    return False


def _apply_one(t):
    """Sequential (list order) application for one tensor."""
    if t.numel() == 0:
        return
    if _is_flat(t):
        _launch_flat_batch((t,))
    else:
        _apply_strided(t)


def foreach_sin_(self):
    tensors = self
    if not isinstance(tensors, (list, tuple)):
        raise TypeError("argument 'self' must be tuple of Tensors")
    if len(tensors) == 0:
        raise RuntimeError("Tensor list must have at least one tensor.")
    for t in tensors:
        if not isinstance(t, torch.Tensor):
            raise TypeError("argument 'self' must be tuple of Tensors")
    # validate every element before mutating any of them
    for t in tensors:
        if not t.dtype.is_floating_point:
            raise RuntimeError(
                "result type Float can't be cast to the desired output type "
                + str(t.dtype).replace("torch.", "").capitalize()
            )
    if _has_alias(tensors):
        for t in tensors:
            _apply_one(t)
        return None
    groups = {}
    gappy = None
    for t in tensors:
        if t.numel() == 0:
            continue
        if _is_flat(t):
            key = t.dtype
            lst = groups.get(key)
            if lst is None:
                groups[key] = [t]
            else:
                lst.append(t)
        elif gappy is None:
            gappy = [t]
        else:
            gappy.append(t)
    for lst in groups.values():
        n = len(lst)
        if n <= _MAX_NT:
            _launch_flat_batch(lst)
        else:
            for i in range(0, n, _MAX_NT):
                _launch_flat_batch(lst[i : i + _MAX_NT])
    if gappy is not None:
        for t in gappy:
            _apply_strided(t)
    return None
